"""OHLCV parsing and bar-level validation primitives (stdlib only)."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Bar:
 date: str # ISO-8601 date; kept as string to avoid timezone surprises
 open: float
 high: float
 low: float
 close: float
 volume: int


def parse_bar(line: str):
 """Parse one CSV line: date,open,high,low,close,volume.

 Returns None for blank lines; raises ValueError on malformed rows.
 """
 parts = line.strip().split(",")
 if parts == [""]:
 return None
 if len(parts) != 6:
 raise ValueError(f"expected 6 fields, got {len(parts)}: {line!r}")
 date, o, h, l, c, v = parts
 return Bar(date=date, open=float(o), high=float(h), low=float(l),
 close=float(c), volume=int(v))


def validate_bar(bar: Bar):
 """Return a list of human-readable issues; empty list means clean."""
 issues = []
 if not bar.low <= bar.high:
 issues.append("low > high")
 if not bar.low <= bar.close <= bar.high:
 issues.append("close outside [low, high]")
 if not bar.low <= bar.open <= bar.high:
 issues.append("open outside [low, high]")
 if bar.volume < 0:
 issues.append("negative volume")
 return issues
